using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements;
namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Temporal;
internal static class AstronomyTemporalMeasurementValidator{public static IEnumerable<AstronomyKnowledgeValidationIssue> Validate(AstronomyMeasurement m,string path,string ruleId,AstronomyKnowledgeDomain domain,AstronomyKnowledgePayloadFamily family){if(string.IsNullOrWhiteSpace(m.Unit.Code)) yield return Issue(AstronomyTemporalValidationCodes.MeasurementUnitInvalid,"Measurement unit code is required.",path+".unit.code",ruleId,domain,family); if(!Enum.IsDefined(m.Unit.Dimension)) yield return Issue(AstronomyTemporalValidationCodes.MeasurementUnitInvalid,"Measurement unit dimension must be defined.",path+".unit.dimension",ruleId,domain,family); if(m.Precision is { } p && (!Enum.IsDefined(p.Kind)||p.Digits>AstronomyMeasurementPrecision.MaxDigits||p.Kind==AstronomyPrecisionKind.DecimalPlaces&&p.Digits<0||p.Kind==AstronomyPrecisionKind.SignificantFigures&&p.Digits<=0)) yield return Issue(AstronomyTemporalValidationCodes.MeasurementPrecisionInvalid,"Measurement precision must use a defined kind and supported digit count.",path+".precision",ruleId,domain,family); if(m.Uncertainty is { } u && (!Enum.IsDefined(u.Kind)||u.LowerValue<0||u.UpperValue<0||((u.Kind==AstronomyUncertaintyKind.SymmetricAbsolute||u.Kind==AstronomyUncertaintyKind.StandardDeviation)&&u.LowerValue!=u.UpperValue)||(u.Kind==AstronomyUncertaintyKind.RelativePercentage&&(u.LowerValue>100||u.UpperValue>100)))) yield return Issue(AstronomyTemporalValidationCodes.MeasurementUncertaintyInvalid,"Measurement uncertainty must be structurally consistent.",path+".uncertainty",ruleId,domain,family);} static AstronomyKnowledgeValidationIssue Issue(string c,string m,string p,string r,AstronomyKnowledgeDomain d,AstronomyKnowledgePayloadFamily f)=>new(c,AstronomyKnowledgeValidationSeverity.Error,m,p,r,d,f);}
